export default {
  title: 'CSS Components/Button',
  
};

export const Overview = {
  render: () => /*html*/`
  <table class="story">
    <thead>
        <tr><th></th><th><code>(primary)</code></th><th><code>.button-secondary</code></th><th><code>.button-tertiary</code></th></tr>
    </thead>
    <tbody>
        <tr>
            <th></th>
            <td><button>Primary</button></td>
            <td><button class="button-secondary">Secondary</button></td>
            <td><button class="button-tertiary">Tertiary</button></td>
        </tr>
        <tr>
            <th><code>[disabled]</code></th>
            <td><button disabled>Primary</button></td>
            <td><button disabled class="button-secondary">Secondary</button></td>
            <td><button disabled class="button-tertiary">Tertiary</button></td>
        </tr>
        <tr>
            <th><code>:hover</code> / <code>.--hover</code></th>
            <td><button class="--hover">Primary</button></td>
            <td><button class="--hover button-secondary">Secondary</button></td>
            <td><button class="--hover button-tertiary">Tertiary</button></td>
        </tr>
        <tr>
            <th><code>:active</code> / <code>.--active</code></th>
            <td><button class="--active">Primary</button></td>
            <td><button class="--active button-secondary">Secondary</button></td>
            <td><button class="--active button-tertiary">Tertiary</button></td>
        </tr>
        <tr>
            <th><code>.button-sm</code></th>
            <td><button class="button-sm">Primary</button></td>
            <td><button class="button-sm button-secondary">Secondary</button></td>
            <td><button class="button-sm button-tertiary">Tertiary</button></td>
        </tr>
        <tr><td><br></td></tr>
        <tr>
            <th><code>:focus</code> / <code>.--focus</code></th>
            <td><button class="--focus">Primary</button></td>
            <td><button class="--focus button-secondary">Secondary</button></td>
            <td><button class="--focus button-tertiary">Tertiary</button></td>
        </tr>
        <tr><td><br></td></tr>
        <tr>
            <th>icons</th>
            <td><button>Primary <i class="fa-sharp fa-light fa-diamond"></i></button></td>
            <td><button class="button-secondary"><i class="fa-sharp fa-light fa-diamond"></i> Secondary</button></td>
            <td><button class="button-tertiary"><i class="fa-sharp fa-light fa-diamond"></i>Tertiary<i class="fa-sharp fa-light fa-diamond"></i></button></td>
        </tr>
        <tr>
            <th><code>&lt;input&gt;</code></th>
            <th><code>[type=submit]</code></th>
            <th><code>[type=button]</code></th>
            <th><code>[type=reset]</code></th>
        </tr>
        <tr>
            <th></th>
            <td><input type="submit" value="Submit"></td>
            <td><input type="button" value="Button"></td>
            <td><input type="reset" value="Reset"></td>
        </tr>
    </tbody>
  </table>
  `,
};